local Compkiller = loadstring(game:HttpGet("https://raw.githubusercontent.com/AmeloxRUS/guicompkiller/refs/heads/main/gui"))();

Compkiller:Loader("rbxassetid://125807422578362", 2.5).yield();




local Window = Compkiller.new({
	Name = "ColdTeam X",
	Keybind = "RightAlt",
	Logo = "rbxassetid://125807422578362",
	Scale = Compkiller.Scale.Window, 
	TextSize = 15,
});

local Watermark = Window:Watermark();
local Time = Watermark:AddText({
	Icon = "timer",
	Text = "TIME",
});

task.spawn(function()
	while true do task.wait()
		Time:SetText(Compkiller:GetTimeNow());
	end
end)

local NormalTab = Window:DrawTab({
	Name = "Example Tab",
	Icon = "coldteamx",
});

local ContainerTab = Window:DrawContainerTab({
	Name = "Extract Tabs",
	Icon = "contact",
});


local ExtractTab = ContainerTab:DrawTab({
	Name = "Tab 1",
	Type = "Double"
});


local SingleExtractTab = ContainerTab:DrawTab({
	Name = "Tab 2",
	Type = "Single",
	EnableScrolling = true, 
});
local NormalSection = NormalTab:DrawSection({
	Name = "Section",
	Position = 'left'	
});

local player = game.Players.LocalPlayer

local speedLoop
local isRunning = false

local Toggle = NormalSection:AddToggle({
Name = "Change speed",
Flag = "Toggle_Example",
Default = false,
Callback = function(Value)
local character = player.Character or player.CharacterAdded:Wait()
local humanoid = character:WaitForChild("Humanoid")


    if Value == true then
        isRunning = true
        speedLoop = task.spawn(function()
            while isRunning do
                wait(0.1)
                humanoid.WalkSpeed = 150
            end
        end)
    else
        isRunning = false
        if speedLoop then
            task.cancel(speedLoop)
            speedLoop = nil
        end
        humanoid.WalkSpeed = 16
    end
end
})

